pub fn contains_consecutive_numbers(a: &[i32]) -> bool {
    // If there are fewer than 2 elements, no adjacent pair can satisfy the condition.
    if a.len() < 2 {
        return false;
    }

    // Iterate over each adjacent window of size 2 and check if the second
    // element is exactly one greater than the first.
    a.windows(2).any(|w| w[0] + 1 == w[1])
}

