        assert!(contains_consecutive_numbers(&[1, 2]));           // 1 + 1 == 2
        assert!(contains_consecutive_numbers(&[5, 6, 1, 2]));     // 5 + 1 == 6
        assert!(contains_consecutive_numbers(&[0, -1, 0, 1]));    // -1 + 1 == 0
        assert!(!contains_consecutive_numbers(&[1]));            // only one element
        assert!(!contains_consecutive_numbers(&[1, 1, 1, 1]));    // no increments
        assert!(!contains_consecutive_numbers(&[10, 8, 7, 5]));   // strictly decreasing
        assert!(!contains_consecutive_numbers(&[-2, -2, -1, -3])); // -2+1 != -2, -2+1== -1? but index mismatch
